package com.shubham.salarytracker;
import org.json.*;
import java.util.*;

/** Pure decision rules: never resolve overlapping device edits by timestamp. */
final class SyncPolicy {
 static String canonical(Object value)throws Exception{if(value instanceof JSONObject){JSONObject o=(JSONObject)value;List<String> keys=new ArrayList<>();o.keys().forEachRemaining(keys::add);Collections.sort(keys);StringBuilder b=new StringBuilder("{");for(String k:keys){if(b.length()>1)b.append(',');b.append(JSONObject.quote(k)).append(':').append(canonical(o.get(k)));}return b.append('}').toString();}if(value instanceof JSONArray){JSONArray a=(JSONArray)value;StringBuilder b=new StringBuilder("[");for(int i=0;i<a.length();i++){if(i>0)b.append(',');b.append(canonical(a.get(i)));}return b.append(']').toString();}return value==null||value==JSONObject.NULL?"null":value instanceof String?JSONObject.quote((String)value):value.toString();}
 static String digest(String text)throws Exception{return DriveBackup.hash(canonical(new JSONObject(text)));}
 static JSONArray heads(JSONArray files)throws Exception{Set<String> parents=new HashSet<>();List<JSONObject> snapshots=new ArrayList<>();for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);JSONObject info;try{info=new JSONObject(f.optString("description","{}"));}catch(Exception e){continue;}if(info.optInt("salarySync")!=1)continue;snapshots.add(f);JSONArray p=info.optJSONArray("parents");if(p!=null)for(int j=0;j<p.length();j++)parents.add(p.getString(j));}JSONArray out=new JSONArray();for(JSONObject f:snapshots)if(!parents.contains(f.getString("id")))out.put(f);return out;}
 static String decide(String localHash,String baseHash,String baseId,JSONArray heads,boolean empty)throws Exception{if(heads.length()>1)return "conflict";if(heads.length()==0)return "upload";String remote=heads.getJSONObject(0).getString("id");if(remote.equals(baseId))return localHash.equals(baseHash)?"current":"upload";if(localHash.equals(baseHash)||empty)return "pull";return baseId.isEmpty()?"conflict":"merge";}
 static boolean empty(JSONObject d){for(String k:Arrays.asList("accounts","records","transfers","leaves","budgets","schedules","adjustments","moneyMoves")){JSONArray a=d.optJSONArray(k);if(a!=null&&a.length()>0)return false;}return true;}
 static JSONObject merge(JSONObject base,JSONObject local,JSONObject remote)throws Exception{JSONObject out=new JSONObject();Set<String> keys=new TreeSet<>();base.keys().forEachRemaining(keys::add);local.keys().forEachRemaining(keys::add);remote.keys().forEachRemaining(keys::add);Set<String> collections=new HashSet<>(Arrays.asList("accounts","records","transfers","leaves","budgets","schedules","adjustments","moneyMoves"));for(String k:keys){Object b=base.opt(k),l=local.opt(k),r=remote.opt(k);if(collections.contains(k)){out.put(k,mergeRows(b instanceof JSONArray?(JSONArray)b:new JSONArray(),l instanceof JSONArray?(JSONArray)l:new JSONArray(),r instanceof JSONArray?(JSONArray)r:new JSONArray()));continue;}Object selected=choose(b,l,r);if(selected!=null)out.put(k,selected);}return out;}
 private static Object choose(Object b,Object l,Object r)throws Exception{String bs=canonical(b),ls=canonical(l),rs=canonical(r);if(ls.equals(rs)||rs.equals(bs))return l;if(ls.equals(bs))return r;throw new IllegalStateException("Both devices changed the same item");}
 private static JSONArray mergeRows(JSONArray b,JSONArray l,JSONArray r)throws Exception{Map<String,JSONObject> bm=map(b),lm=map(l),rm=map(r);LinkedHashSet<String> ids=new LinkedHashSet<>();ids.addAll(bm.keySet());ids.addAll(lm.keySet());ids.addAll(rm.keySet());JSONArray out=new JSONArray();for(String id:ids){Object row=choose(bm.get(id),lm.get(id),rm.get(id));if(row!=null)out.put(row);}return out;}
 private static Map<String,JSONObject> map(JSONArray a)throws Exception{Map<String,JSONObject> out=new LinkedHashMap<>();for(int i=0;i<a.length();i++){JSONObject row=a.getJSONObject(i);String id=row.getString("id");if(out.put(id,row)!=null)throw new IllegalStateException("Duplicate IDs");}return out;}
}
